const pptxgen = require('pptxgenjs');
let pres = new pptxgen();

// Step 1: Select 'Midnight Executive' theme and 'LAYOUT_WIDE' layout
pres.layout = 'LAYOUT_WIDE'; // 13.3" x 7.5"
const theme = {
    primary: "1E2761", // navy
    secondary: "CADCFC", // ice blue
    accent: "F96167", // coral (not used directly in theme but for elements)
    charcoal: "36454F"
};

// Helper function for text defaults
function getTextStyle(fontSize, color = 'FFFFFF', bold = false) {
    return { fontFace: 'Calibri', fontSize: fontSize, color: color, bold: bold, margin: 0 };
}

// --- Slide 1: Title Slide ---
let slide1 = pres.addSlide();
slide1.slideNumber = { x: 0.5, y: "95%", color: theme.secondary };
slide1.bkgd = { fill: theme.primary };
slide1.addText('Incredible India', { x: 1, y: 1.5, fontSize: 48, color: theme.secondary, bold: true, align: 'center', w: '80%' });
slide1.addText('A Journey Through Culture, Innovation, and Diversity', { x: 1, y: 3, fontSize: 24, color: theme.secondary, align: 'center', w: '80%' });
// Add a subtle visual motif - a rounded rectangle element (simulating visual quality)
slide1.addShape(pres.ShapeType.ROUNDED_RECTANGLE, { x: 0, y: 6.8, w: '100%', h: 0.7, fill: theme.charcoal, transparency: 70 });


// --- Slide 2: Culture & Heritage ---
let slide2 = pres.addSlide();
slide2.bkgd = { fill: 'FFFFFF' };
slide2.addText('Culture & Heritage', getTextStyle(36, theme.charcoal, true, 0.5));

const cultureText = [
    { text: "Diverse Traditions: A tapestry of languages, religions, and festivals.", options: { bullet: true, breakLine: true, ...getTextStyle(16, theme.charcoal) } },
    { text: "Ancient History: From Indus Valley to powerful empires.", options: { bullet: true, breakLine: true, ...getTextStyle(16, theme.charcoal) } },
    { text: "Unity in Diversity: The core philosophy.", options: { bullet: true, ...getTextStyle(16, theme.charcoal) } },
];
slide2.addText(cultureText, { x: 0.5, y: 1.5, w: '60%' });


// --- Slide 3: Economic Powerhouse ---
let slide3 = pres.addSlide();
slide3.bkgd = { fill: theme.secondary };
slide3.addText('Economic Powerhouse', getTextStyle(36, theme.primary, true));

// Example of chart based on skill guidance (native charts)
slide3.addText('GDP Growth & Innovation', { x: 0.5, y: 1.5, ...getTextStyle(24, theme.primary, true) });
const chartData = [
    {
        name: "Growth",
        labels: ["2023", "2024", "2025 (Est)"],
        values: [7.2, 7.5, 7.8]
    }
];
slide3.addChart(pres.ChartType.bar, chartData, {
    x: 0.5, y: 2.5, w: 12, h: 4.5,
    chartColors: [theme.primary, theme.charcoal, theme.accent],
    showTitle: true,
    title: "Projected GDP Growth (%)",
    showValue: true,
    dataLabelPosition: 'ctr',
    valAxisLabelColor: theme.primary,
    catAxisLabelColor: theme.primary,
});


// --- Slide 4: Future Vision ---
let slide4 = pres.addSlide();
slide4.bkgd = { fill: theme.primary };
slide4.addText('Future Vision', getTextStyle(36, theme.secondary, true));

const visionText = [
    { text: "AI & Generative AI Hub: Leading global innovation.", options: { bullet: true, breakLine: true, ...getTextStyle(18, theme.secondary) } },
    { text: "Sustainable Development: Balancing growth with environment.", options: { bullet: true, breakLine: true, ...getTextStyle(18, theme.secondary) } },
    { text: "Global Leader: Shaping the future world order.", options: { bullet: true, ...getTextStyle(18, theme.secondary) } },
];
slide4.addText(visionText, { x: 1, y: 2, w: '80%' });


// Step 4: Save the presentation to C:/Users/achal/Desktop/India_Presentation.pptx
const outputPath = 'C:/Users/achal/Desktop/India_Presentation.pptx';
pres.writeFile(outputPath);

const pptxgen = require('pptxgenjs');
let pres = new pptxgen();

pres.layout = 'LAYOUT_WIDE';
const theme = {
    primary: "1E2761", // navy
    secondary: "CADCFC", // ice blue
    accent: "F96167", // coral
    charcoal: "36454F",
    cream: "F5F5F5"
};

function getTextStyle(fontSize, color = theme.cream, bold = false, margin = 0.5) {
    return { fontFace: 'Calibri', fontSize: fontSize, color: color, bold: bold, margin: margin };
}

// Slide 1: Title
let slide1 = pres.addSlide();
slide1.bkgd = { fill: theme.primary };
slide1.addText('Incredible India: A Global Powerhouse', { x: 0.5, y: 2, ...getTextStyle(48, theme.secondary, true, 0) });
slide1.addText('A Deep Dive into Culture, Economy, and Future Vision', { x: 0.5, y: 4, ...getTextStyle(24, theme.secondary, false, 0) });

// Slide 2: Culture & Heritage (Deep Insight)
let slide2 = pres.addSlide();
slide2.bkgd = { fill: theme.cream };
slide2.addText('Culture & Heritage: Unity in Diversity', { x: 0.5, y: 0.5, ...getTextStyle(36, theme.charcoal, true) });
const cultureContent = [
    { text: "Diverse Traditions: India is a vibrant tapestry with 22 major languages, countless dialects, and diverse religious philosophies, embodying profound cultural pluralism.", options: { bullet: true, breakLine: true, ...getTextStyle(18, theme.charcoal) } },
    { text: "Ancient Legacy: From the spiritual philosophies of Vedanta to architectural marvels like the Taj Mahal, India's ancient history (Indus Valley Civilization) forms a powerful 'soft power' asset globally.", options: { bullet: true, breakLine: true, ...getTextStyle(18, theme.charcoal) } },
    { text: "Socio-Economic Dynamics: This rich heritage drives national identity but also navigates complex challenges related to social equity, modernization, and balancing tradition with contemporary progress.", options: { bullet: true, ...getTextStyle(18, theme.charcoal) } },
];
slide2.addText(cultureContent, { x: 1, y: 1.8, w: '85%' });

// Slide 3: Economic Powerhouse (Growth Drivers)
let slide3 = pres.addSlide();
slide3.bkgd = { fill: 'FFFFFF' };
slide3.addText('Economic Powerhouse: Growth Drivers & Vision', { x: 0.5, y: 0.5, ...getTextStyle(36, theme.primary, true) });
const economyContent = [
    { text: "Demographic Dividend: A massive, young workforce drives domestic consumption and innovation, positioning India as the fastest-growing major economy.", options: { bullet: true, breakLine: true, ...getTextStyle(18, theme.charcoal) } },
    { text: "Digital Economy: Rapid digitalization and robust Digital Public Infrastructure (DPI) foster unprecedented growth in Fintech, E-commerce, and service sectors.", options: { bullet: true, breakLine: true, ...getTextStyle(18, theme.charcoal) } },
    { text: "Strategic Investments: Focus on infrastructure development and 'Make in India' manufacturing aims to establish India as a critical hub in resilient global supply chains.", options: { bullet: true, ...getTextStyle(18, theme.charcoal) } },
];
slide3.addText(economyContent, { x: 1, y: 1.8, w: '85%' });


// Slide 4: Geopolitics & Global Role
let slide4 = pres.addSlide();
slide4.bkgd = { fill: theme.secondary };
slide4.addText('Geopolitics & Global Role', { x: 0.5, y: 0.5, ...getTextStyle(36, theme.primary, true) });
const geoContent = [
    { text: "Strategic Autonomy: India practices multi-alignment, balancing relationships with major powers and asserting strategic independence in a multipolar world order.", options: { bullet: true, breakLine: true, ...getTextStyle(18, theme.primary) } },
    { text: "Regional Stability: A pivotal player in South Asian geopolitics and the Indo-Pacific, crucial for maintaining regional balance.", options: { bullet: true, breakLine: true, ...getTextStyle(18, theme.primary) } },
    { text: "Multilateral Leadership: Active engagement in forums like G20, QUAD, and SCO, advocating for reformed multilateral governance and representing the Global South.", options: { bullet: true, ...getTextStyle(18, theme.primary) } },
];
slide4.addText(geoContent, { x: 1, y: 1.8, w: '85%' });


// Slide 5: Future Technological Vision
let slide5 = pres.addSlide();
slide5.bkgd = { fill: theme.primary };
slide5.addText('Future Technological Vision', { x: 0.5, y: 0.5, ...getTextStyle(36, theme.secondary, true) });
const techContent = [
    { text: "AI & Generative AI: Aiming to become a leading global hub for AI innovation, focusing on ethical deployment and leveraging AI for socio-economic challenges.", options: { bullet: true, breakLine: true, ...getTextStyle(18, theme.secondary) } },
    { text: "Space Exploration: Ambitious space programs (ISRO) demonstrating advanced capabilities, fostering deep-tech ecosystems, and positioning for commercial space leadership.", options: { bullet: true, breakLine: true, ...getTextStyle(18, theme.secondary) } },
    { text: "Sustainable & Digital Future: Pioneering sustainable development goals driven by cutting-edge digital infrastructure.", options: { bullet: true, ...getTextStyle(18, theme.secondary) } },
];
slide5.addText(techContent, { x: 1, y: 1.8, w: '85%' });


// Step 4: Save
const outputPath = 'C:/Users/achal/Desktop/India_Deep_Presentation.pptx';
pres.writeFile(outputPath);
